import { EventEmitter } from 'node:events';
import { connectPresence } from './src/connect.js';
const socket = new EventEmitter();
const seen = [];
socket.connect = () => socket.emit('presence', 'initial-online');
const dispose = connectPresence(socket, value => seen.push(value));
console.log('Synchronous initial presence:', JSON.stringify({expected:['initial-online'], actual:seen}));
socket.emit('presence', 'later-online');
console.log('After subsequent event:', JSON.stringify(seen));
dispose();
const failed = new EventEmitter();
failed.connect = () => { throw new Error('connect failed'); };
try { connectPresence(failed, () => {}); } catch (error) { console.log('Failed connect:', error.message, 'listeners:', failed.listenerCount('presence')); }
const shared = new EventEmitter();
shared.connect = () => {};
const other = () => {};
shared.on('presence', other);
const cleanup = connectPresence(shared, () => {});
cleanup();
console.log('Unrelated subscription retained:', shared.listeners('presence').length === 1 && shared.listeners('presence')[0] === other);
